<?php
if(!defined('ABSPATH'))exit;
class WP_FixPilot_Performance_Repair {
 public static function analyze(){return array('duplicate_cron'=>self::duplicate_cron_candidates(),'stale_single_cron'=>self::stale_single_events(),'cart_fragments'=>self::cart_fragments_status(),'object_cache'=>wp_using_ext_object_cache());}
 public static function duplicate_cron_candidates(){ $cron=_get_cron_array();$seen=array();$dupes=array();foreach((array)$cron as $ts=>$hooks)foreach($hooks as $hook=>$events)foreach($events as $sig=>$e){$key=$hook.'|'.md5(wp_json_encode(isset($e['args'])?$e['args']:array())).'|'.(isset($e['schedule'])?$e['schedule']:'');if(!empty($e['schedule'])&&isset($seen[$key])&&abs((int)$ts-(int)$seen[$key]['ts'])<60)$dupes[]=array('hook'=>$hook,'timestamp'=>(int)$ts,'args'=>isset($e['args'])?$e['args']:array(),'schedule'=>$e['schedule']);else$seen[$key]=array('ts'=>(int)$ts); }return $dupes; }
 public static function cleanup_duplicate_cron(){ $n=0;foreach(array_slice(self::duplicate_cron_candidates(),0,100) as $e){if(false!==wp_unschedule_event($e['timestamp'],$e['hook'],$e['args']))$n++;}return $n; }
 public static function stale_single_events(){ $cron=_get_cron_array();$out=array();$cut=time()-DAY_IN_SECONDS;foreach((array)$cron as $ts=>$hooks){if((int)$ts>$cut)continue;foreach($hooks as $hook=>$events)foreach($events as $e)if(empty($e['schedule']))$out[]=array('hook'=>$hook,'timestamp'=>(int)$ts,'args'=>isset($e['args'])?$e['args']:array());}return $out; }
 public static function cleanup_stale_single_events(){ $n=0;foreach(array_slice(self::stale_single_events(),0,100) as $e){if(false!==wp_unschedule_event($e['timestamp'],$e['hook'],$e['args']))$n++;}return $n; }
 public static function cart_fragments_status(){return array('woocommerce_active'=>class_exists('WooCommerce'),'script_registered'=>wp_script_is('wc-cart-fragments','registered'),'auto_disable'=>false,'reason'=>'Automatic disabling is intentionally blocked because themes/mini-cart widgets may depend on it.');}
 public static function repair_plan(){ $a=self::analyze();$p=array();if(count($a['duplicate_cron']))$p[]=array('severity'=>'attention','action'=>'cleanup_duplicate_cron','count'=>count($a['duplicate_cron']),'label'=>'Remove near-duplicate recurring cron events');if(count($a['stale_single_cron']))$p[]=array('severity'=>'danger','action'=>'cleanup_stale_single_cron','count'=>count($a['stale_single_cron']),'label'=>'Remove stale one-time cron events older than 24h');if(!$a['object_cache'])$p[]=array('severity'=>'attention','action'=>'recommend_object_cache','label'=>'Persistent object cache is not active','automatic'=>false);return $p;}
}
